"""Logos de cada liga y copa (embebidos como data URI: andan en la web y en la PC sin
descargar nada). Fuentes: ESPN (Liga Profesional, Copa Argentina y copas CONMEBOL) y TheSportsDB
(Primera Nacional, Federal A, Primera B, Primera C). El del Regional Amateur es un
distintivo propio del simulador."""

LOGOS = {
    "Primera División": "data:image/png;base64,",
    "Primera Nacional": "data:image/png;base64,",
    "Federal A": "data:image/png;base64,",
    "Primera B": "data:image/png;base64,",
    "Primera C": "data:image/png;base64,",
    "Regional Amateur": "data:image/svg+xml;base64,",
    "Copa Argentina": "data:image/png;base64,",
    "Copa Libertadores": "data:image/png;base64,",
    "Copa Sudamericana": "data:image/png;base64,",
    "Recopa Sudamericana": "data:image/png;base64,",
}


def logo_img(nombre, size=22, clase="logo-comp"):
    """<img> con el logo de una liga o copa (o nada si no tiene)."""
    url = LOGOS.get(nombre)
    if not url:
        return ""
    return (f'<img class="{clase}" src="{url}" width="{size}" height="{size}" alt="" '
            f'title="{nombre}">')
